cd ~/workspace && echo '' | base64 -d | gunzip > /tmp/CaixaEstoque.tsx && node -e '
const fs=require("fs"),crypto=require("crypto");
const novo=fs.readFileSync("/tmp/CaixaEstoque.tsx");
if(crypto.createHash("sha256").update(novo).digest("hex").slice(0,16)!=="c040748f5a359487"){console.log("❌ O comando chegou cortado. Copie de novo o bloco inteiro.");process.exit(1);}
const B="artifacts/fechamento/src/";
if(!fs.existsSync(B+"lib/supabaseClient.ts")){console.log("❌ Não achei lib/supabaseClient.ts. Nada foi alterado.");process.exit(1);}
const A=B+"App.tsx";let app=fs.readFileSync(A,"utf8");
const linha=app.split("\n").find(l=>l.includes("<TaxasMaquininha"));
if(!linha||!app.includes("setPage")){console.log("❌ Não reconheci o App.tsx. Nada foi alterado.");process.exit(1);}
fs.writeFileSync(B+"pages/CaixaEstoque.tsx",novo);
if(!app.includes("CaixaEstoque")){
  fs.copyFileSync(A,A+".antes-caixa");
  app=app.replace(/(import TaxasMaquininha[^\n]*\n)/,"$1import CaixaEstoque from \"@/pages/CaixaEstoque\";\n");
  const ind=linha.match(/^\s*/)[0];
  const novaLinha=ind+"{(page as string) === \"caixa\" && <CaixaEstoque onBack={() => setPage(\"fechamento\" as any)} />}\n"+ind+"{(page as string) !== \"caixa\" && <button onClick={() => setPage(\"caixa\" as any)} style={{position:\"fixed\",right:16,bottom:16,zIndex:60,border:\"none\",borderRadius:999,padding:\"12px 18px\",fontWeight:800,fontSize:15,color:\"#fff\",background:\"linear-gradient(135deg,#0d1b3e,#1a3fa8)\",boxShadow:\"0 6px 20px rgba(13,27,62,.3)\",cursor:\"pointer\"}}>💰 Caixa</button>}";
  app=app.replace(linha,linha+"\n"+novaLinha);
  fs.writeFileSync(A,app);
  console.log("✓ Botão 💰 Caixa adicionado (App.tsx antigo guardado em App.tsx.antes-caixa)");
}else console.log("✓ Tela do Caixa atualizada");
console.log("\n✅ PRONTO. Clique em Stop e depois em Run.");
'
